-- Preserve old receipts/inventory, replace only discontinued display slots.
on conflict(stable_id) do update set asset=excluded.asset,metadata=excluded.metadata,title=excluded.title,status='active',updated_at=now();
update catalog_items set status='retired',updated_at=now() where (category='dresser_plants' and stable_id not like 'burrow_kettle_%') or (category='shelf_decor' and metadata->>'starter' is distinct from 'true');
update room_loadouts set item_id='burrow_kettle_01_04',updated_at=now() where slot='dresser_plant' and item_id not like 'burrow_kettle_%';
update room_loadouts set item_id='burrow_art_shelf_decor_01',updated_at=now() where slot='shelf_decor' and item_id<>'burrow_art_shelf_decor_01';
notify pgrst,'reload schema';
